if git diff --cached --quiet; then
  echo "Nothing to commit -- already up to date."
else
  git commit -m "40% deposit at booking, 60% balance when the work is done"
  git push
fi

echo
echo "✅ pushed"
echo "Vercel will redeploy in a minute or two. Then hard-refresh: Cmd+Shift+R"
